import 'dart:convert';

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

import 'owl_expression.dart';

/// One of the 20 owl color themes (JSON-driven).
///
/// Non-classic skins load recolored copies of the real pack files from
/// `assets/rive/skins/` (generated by `tool/generate_owl_skins_test.dart`).
class OwlSkin {
  const OwlSkin({
    required this.id,
    required this.name,
    required this.cardBg,
    required this.body,
    required this.accent,
    required this.belly,
    required this.bow,
  });

  final String id;
  final String name;
  final Color cardBg;
  final Color body;
  final Color accent;
  final Color belly;
  final Color bow;

  static const classicBrownId = 'classic_brown';
  static const skinsRiveDir = 'assets/rive/skins';

  bool get isClassic => id == classicBrownId;

  String get thumbnailPath => 'assets/images/skins/$id.png';

  List<Color> get paletteDots => [body, accent, belly, bow];

  /// Rive file to load for [expression] in this skin.
  String riveAssetFor(OwlExpression expression) {
    if (isClassic) return expression.assetPath;
    if (expression.assetPath == OwlExpression.packAssetPath) {
      return '$skinsRiveDir/owl_$id.riv';
    }
    if (expression.assetPath.contains('owl_sleep')) {
      return '$skinsRiveDir/owl_sleep_$id.riv';
    }
    // listen/talk: classic custom riv until skin variants exist
    return expression.assetPath;
  }

  factory OwlSkin.fromJson(Map<String, dynamic> json) {
    return OwlSkin(
      id: json['id'] as String,
      name: json['name'] as String,
      cardBg: _parseColor(json['cardBg'] as String),
      body: _parseColor(json['body'] as String),
      accent: _parseColor(json['accent'] as String),
      belly: _parseColor(json['belly'] as String),
      bow: _parseColor(json['bow'] as String),
    );
  }

  static Color _parseColor(String hex) {
    var value = hex.replaceFirst('#', '');
    if (value.length == 6) value = 'FF$value';
    return Color(int.parse(value, radix: 16));
  }
}

/// Loads [assets/data/owl_skins.json] once.
class OwlSkinCatalog {
  OwlSkinCatalog(this.skins, this.defaultId);

  final List<OwlSkin> skins;
  final String defaultId;

  static OwlSkinCatalog? _cached;

  OwlSkin get defaultSkin {
    for (final skin in skins) {
      if (skin.id == defaultId) return skin;
    }
    return skins.first;
  }

  OwlSkin byId(String id) {
    for (final skin in skins) {
      if (skin.id == id) return skin;
    }
    return defaultSkin;
  }

  int numberOf(OwlSkin skin) => skins.indexOf(skin) + 1;

  static Future<OwlSkinCatalog> load({AssetBundle? bundle}) async {
    if (_cached != null) return _cached!;
    final raw = await (bundle ?? rootBundle)
        .loadString('assets/data/owl_skins.json');
    final map = jsonDecode(raw) as Map<String, dynamic>;
    final list = (map['skins'] as List<dynamic>)
        .map((e) => OwlSkin.fromJson(e as Map<String, dynamic>))
        .toList(growable: false);
    _cached = OwlSkinCatalog(
      list,
      map['defaultId'] as String? ?? OwlSkin.classicBrownId,
    );
    return _cached!;
  }

  @visibleForTesting
  static void debugReset() {
    _cached = null;
  }
}
